use std::fs

fn main() {
    let n = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut count: Vec<int> = [0; 200001]
    let mut largest: Vec<int> = [0; 200001]
    let mut i = 2
    while i * i <= n {
        if sieve[i] {
            let mut j = i * i
            while j <= n {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut last = 0
    let mut k = 2
    while k <= n {
        if sieve[k] {
            c += 1
            last = k
        }
        count[k] = c
        largest[k] = last
        k += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut out: Vec<string> = []
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let v = t.parse::<int>().unwrap_or(0)
        if v < 2 {
            out.push("0 none")
        } else {
            out.push("${count[v]} ${largest[v]}")
        }
    }
    println(out.join("\n"))
}

